class Capture:

    def __init__(self, process):
        self.ready = queue.Queue(maxsize=1)
        self.lock = threading.Lock()
        self.count = 0
        self.error = None
        self.logs = {'stdout': bytearray(), 'stderr': bytearray()}
        self.threads = []
        for label, stream in [('stdout', process.stdout), ('stderr', process.stderr)]:
            thread = threading.Thread(target=self._read, args=(label, stream), daemon=True)
            thread.start()
            self.threads.append(thread)

    def _read(self, label, stream):
        pending = bytearray()
        first = True
        try:
            while True:
                chunk = os.read(stream.fileno(), 4096)
                if not chunk:
                    break
                with self.lock:
                    remaining = max(0, 16384 - sum(map(len, self.logs.values())))
                    self.logs[label].extend(chunk[:remaining])
                    self.count += len(chunk)
                    if self.count > 16384:
                        self.error = 'OUTPUT_BOUND'
                if label == 'stdout' and first:
                    pending.extend(chunk)
                    if b'\n' in pending:
                        frame = bytes(pending[:pending.index(10) + 1])
                        first = False
                        if len(frame) > 256:
                            self.error = 'BOOTSTRAP_BOUND'
                        else:
                            self.ready.put_nowait(frame)
                    elif len(pending) > 256:
                        self.error = 'BOOTSTRAP_BOUND'
                        first = False
        except BaseException:
            self.error = 'CAPTURE_FAILED'

    def save(self, root, name):
        for thread in self.threads:
            thread.join(2)
        need(all((not thread.is_alive() for thread in self.threads)), 'OWN_PIPE_NOT_RETIRED')
        for label, raw in self.logs.items():
            (root / (name + '.' + label + '.log')).write_bytes(raw)
